'use strict';
const $=id=>document.getElementById(id),fmt=(v,n=2)=>v==null?'未记录':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:n,minimumFractionDigits:n});
let D=null,rows=[],events=[],selected=null,page=0,charts=[],allEvents=[];
const colors={price:'#284a40',fast:'#298b70',slow:'#b49452',red:'#bb665e',blue:'#6b8fb0'};
function renderMetrics(){
const metric=[['年化收益',fmt(D.metrics.cagr_natural_pct)+'%','自然年复合年化'],['最大回撤',fmt(D.metrics.max_drawdown_pct)+'%','原运行完整历史'],['夏普比率',fmt(D.metrics.sharpe_rf0),'无风险利率 = 0'],['期末权益',fmt(D.metrics.end_balance/10000)+' 万','初始资金 100 万元']];
metric.push(['胜率',fmt(D.trade_summary.win_rate_pct)+'%',D.trade_summary.closed_count+' 个已平持仓段'],['盈亏比',fmt(D.trade_summary.payoff_ratio)+' 倍','平均净盈利 / 平均净亏损绝对值']);
$('metrics').innerHTML=metric.map(([l,v,s])=>`<div class="metric"><label>${l}</label><strong>${v}</strong><small>${s}</small></div>`).join('');
$('metricScope').textContent=`上方为 ${D.meta.label} 原运行全品种组合，${D.metrics.start} — ${D.metrics.end}；不随品种或图表区间改变。胜率和盈亏比按扣费后的同合约已平持仓段计算，未平段不计入。品种按当时可用覆盖陆续加入。`;
}
function linePath(data,get,x,y,step=false){let out='',started=false,prev=null;data.forEach((r,i)=>{const v=get(r);if(v==null||!Number.isFinite(v)){started=false;return}const X=x(i),Y=y(v);out+=started?(step?`H${X}V${Y}`:`L${X},${Y}`):`M${X},${Y}`;started=true;prev=v});return out}
function chart(id,data,series,height,opts={}){
 const w=900,L=59,R=20,T=14,B=26,n=data.length;if(!n){$(id).innerHTML='<p class="muted">此区间没有记录。</p>';return}
 const vals=series.flatMap(s=>data.map(s.get)).filter(v=>v!=null&&Number.isFinite(v));let lo=opts.lo??Math.min(...vals),hi=opts.hi??Math.max(...vals);if(!Number.isFinite(lo)){lo=0;hi=1}if(lo===hi){lo-=1;hi+=1}if(opts.lo==null){let pad=(hi-lo)*.13;lo-=pad;hi+=pad}
 const x=i=>L+i/Math.max(1,n-1)*(w-L-R),y=v=>T+(hi-v)/(hi-lo)*(height-T-B);
 let svg=`<svg viewBox="0 0 ${w} ${height}" aria-label="${opts.label||id}" role="img">`;
 for(let k=0;k<4;k++){const v=lo+(hi-lo)*k/3,Y=y(v);svg+=`<line x1="${L}" y1="${Y}" x2="${w-R}" y2="${Y}" stroke="#edf0e9"/><text x="${L-8}" y="${Y+3}" text-anchor="end">${fmt(v,opts.digits??0)}</text>`}
 for(let i of [...new Set([0,Math.floor(n/2),n-1])])svg+=`<text x="${x(i)}" y="${height-6}" text-anchor="middle">${data[i].date}</text>`;
 for(const s of series){const path=linePath(data,s.get,x,y,s.step);if(s.fill&&path)svg+=`<path d="${path}L${x(n-1)},${y(0)}L${x(0)},${y(0)}Z" fill="${s.fill}"/>`;svg+=`<path d="${path}" fill="none" stroke="${s.color}" stroke-width="${s.width||1.7}" ${s.dash?'stroke-dasharray="5 4"':''}/>`}
 if(opts.markers){let counts={};for(const e of events){const i=data.findIndex(r=>r.date===e.date);if(i<0)continue;const color=e.roll?'#8b929c':e.kind==='开多'?'#278168':e.kind==='开空'?'#bf635c':'#688aa4';const offset=counts[i]||0;counts[i]=offset+1;const X=x(i),Y=Math.max(T+5,Math.min(height-B-5,y(data[i].price)-12-offset*14));let mark=e.roll?'◆':e.kind==='开多'?'▲':e.kind==='开空'?'▼':e.kind==='平仓'?'○':e.kind==='加仓'?'＋':e.kind==='减仓'?'−':'↕';svg+=`<g tabindex="0" role="button" aria-label="${e.date} ${e.symbol} ${e.kind}" data-event="${e.id}" style="cursor:pointer"><title>${e.date} ${e.symbol} ${e.kind} ${e.signed_volume}手 · 成交价 ${e.price}</title><circle cx="${X}" cy="${Y-4}" r="9" fill="${selected?.id===e.id?'#e4e6cc':'white'}" fill-opacity=".85"/><text x="${X}" y="${Y}" text-anchor="middle" style="fill:${color};font-size:14px;font-weight:bold">${mark}</text></g>`}}
 svg+=`<line class="crosshair" x1="0" x2="0" y1="${T}" y2="${height-B}" stroke="#7a9682" stroke-dasharray="3 3" visibility="hidden"/></svg>`;$(id).innerHTML=svg;
 const el=$(id).querySelector('svg');charts.push({el,data,x});el.addEventListener('mousemove',ev=>{const rect=el.getBoundingClientRect(),X=(ev.clientX-rect.left)/rect.width*w;const i=Math.max(0,Math.min(n-1,Math.round((X-L)/(w-L-R)*(n-1))));inspectDay(data[i].date)});
 el.querySelectorAll('[data-event]').forEach(g=>{const select=()=>selectEvent(allEvents.find(e=>e.id===g.dataset.event));g.addEventListener('click',select);g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select()}})});
}
function inspectDay(day){for(const c of charts){const i=c.data.findIndex(r=>r.date===day),line=c.el.querySelector('.crosshair');line.setAttribute('visibility',i<0?'hidden':'visible');if(i>=0){line.setAttribute('x1',c.x(i));line.setAttribute('x2',c.x(i))}}const r=rows.find(r=>r.date===day);if(!r)return;const d=r.decision;$('dayInfo').textContent=`${day} · ${r.contract||'无主力记录'}　信号价 ${fmt(r.price)}　实约收盘 ${fmt(r.execution_close)}　信号 ${fmt(d?.forecast)}　目标 ${d?.target??'未记录'} 手　收盘实持 ${r.actual} 手`}
function renderCharts(){charts=[];const ps=[{get:r=>r.price,color:colors.price}];if(['S003','S007'].includes(D.meta.id))ps.push({get:r=>r.fast,color:colors.fast},{get:r=>r.slow,color:colors.slow});if(D.meta.id==='S004')ps.push({get:r=>r.upper,color:colors.fast},{get:r=>r.lower,color:colors.slow});chart('priceChart',rows,ps,260,{markers:true,label:'信号价格、规则参考线与模拟成交日期'});chart('rawChart',rows,[{get:r=>r.decision?.raw_forecast,color:colors.blue}],100,{digits:2,label:'归档原始规则信号'});chart('signalChart',rows,[{get:r=>r.decision?.forecast,color:colors.fast}],100,{lo:-22,hi:22,label:'标准化信号'});chart('positionChart',rows,[{get:r=>r.decision?.target,color:colors.blue,dash:true,step:true},{get:r=>r.actual,color:colors.price,step:true}],115,{label:'目标与实际持仓'});
 let high=1000000;const ac=D.account.map(a=>{high=Math.max(high,a.equity);return {...a,nav:a.equity/1000000,dd:100*(a.equity/high-1)}}).filter(a=>a.date>=$('start').value&&a.date<=$('end').value);chart('equityChart',ac,[{get:r=>r.nav,color:colors.fast}],160,{digits:2,label:'原全品种组合净值'});chart('drawdownChart',ac,[{get:r=>r.dd,color:colors.red,fill:'#f4e7e2'}],85,{hi:0,digits:1,label:'完整历史高点回撤百分比'});if(selected)inspectDay(selected.date);else if(rows.length)inspectDay(rows[rows.length-1].date)}
function selectEvent(e){if(!e)return;selected=e;const d=e.decision;const cause=e.roll?`换月记录：${e.roll.old} → ${e.roll.new}。这是换月日相关委托的成交，不能直接解释为趋势入场或退出。`:d?`决策时标准化信号为 ${fmt(d.forecast)}，目标仓位 ${d.target} 手，决策前当前合约持仓 ${d.actual} 手。成交是归档委托的实际结果；信号正负与本笔买卖方向可能不同（例如减仓）。`:'未找到同日归档决策，原因保持未确认。';
 $('tradeDetail').innerHTML=`<div class="trade-title">${e.roll?'◆ 换月 · ':''}${e.kind}</div><div class="trade-date">${e.date} · ${e.symbol} · 成交 #${e.id}</div><div class="kv">${[['真实成交价',fmt(e.price)],['成交手数变化',(e.signed_volume>0?'+':'')+e.signed_volume],['该合约成交前',e.before+' 手'],['该合约成交后',e.after+' 手'],['委托 / 决策日',e.order_date],['实际成交日',e.date],['手续费',fmt(e.commission)+' 元'],['滑点成本',fmt(e.slippage)+' 元']].map(([l,v])=>`<div><label>${l}</label><b>${v}</b></div>`).join('')}</div><div class="explain"><b>归档事实与决策依据</b><p>${cause}</p></div>${d?`<div class="kv">${[['原始信号',fmt(d.raw_forecast,4)],['每日价格波动率',fmt(d.daily_price_vol,4)],['用于仓位的权益',fmt(d.sizing_capital)+' 元'],['当日品种权重',fmt(d.weight*100)+'%'],['连续目标仓位',fmt(d.continuous_position)+' 手'],['缓冲带',fmt(d.lower)+' ~ '+fmt(d.upper)]].map(([l,v])=>`<div><label>${l}</label><b>${v}</b></div>`).join('')}</div>`:''}<a href="${runLink()}" target="_blank">查看原运行配置 ↗</a>`;
 const idx=events.findIndex(t=>t.id===e.id);if(idx>=0)page=Math.floor(idx/12);renderTable();renderCharts();}
function renderTable(){const count=events.length,pages=Math.max(1,Math.ceil(count/12));page=Math.max(0,Math.min(page,pages-1));$('trades').innerHTML=events.slice(page*12,page*12+12).map(e=>`<tr tabindex="0" data-id="${e.id}" class="${selected?.id===e.id?'selected':''}"><td>${e.date}</td><td>${e.symbol}</td><td>${e.roll?'◆ 换月 / ':''}${e.kind}</td><td>${e.signed_volume>0?'+':''}${e.signed_volume}</td><td>${fmt(e.price)}</td><td>${fmt(e.commission)} / ${fmt(e.slippage)}</td><td>${e.order_date}</td></tr>`).join('')||'<tr><td colspan="7">当前筛选下没有成交记录。</td></tr>';$('pageInfo').textContent=`${page+1} / ${pages}`;$('tradeCount').textContent=`筛选后 ${count} 笔 · 点击查看决策依据`;$('pagePrev').disabled=page===0;$('pageNext').disabled=page>=pages-1;$('trades').querySelectorAll('tr').forEach(tr=>{const f=()=>selectEvent(events.find(e=>e.id===tr.dataset.id));tr.onclick=f;tr.onkeydown=e=>{if(e.key==='Enter')f()}})}
function renderTradeStats(){
 const p=$('product').value,start=$('start').value,end=$('end').value;
 const es=D.closed_episodes.filter(e=>e.product===p&&e.exit_date>=start&&e.exit_date<=end),wins=es.filter(e=>e.net>1e-8),losses=es.filter(e=>e.net< -1e-8);
 const aw=wins.length?wins.reduce((s,e)=>s+e.net,0)/wins.length:null,al=losses.length?-losses.reduce((s,e)=>s+e.net,0)/losses.length:null,ratio=aw!=null&&al!=null?aw/al:null,pf=al!=null?(aw||0)*wins.length/(al*losses.length):null;
 const cells=[['胜率',es.length?fmt(wins.length/es.length*100)+'%':'暂无样本'],['盈亏比',ratio!=null?fmt(ratio)+' 倍':'不可计算'],['盈利因子',pf!=null?fmt(pf):'不可计算'],['已平持仓段',es.length+' 段']];
 $('filteredStats').innerHTML=cells.map(([label,value])=>`<div><label>${label}</label><strong>${value}</strong></div>`).join('');
 $('statsScope').textContent=`${D.products[p].name} · 按平仓日 ${start} — ${end}`;
 $('statsDefinition').textContent=`平均净盈利 ${fmt(aw)} 元；平均净亏损 ${fmt(al)} 元。盈利 ${wins.length} / 亏损 ${losses.length} / 持平 ${es.length-wins.length-losses.length}。同合约空仓→再次空仓算一段，加减仓合并；反手拆段、换月平旧结束一段。按平仓日纳入，开仓可早于筛选起点；未平段排除。盈亏比＝平均净盈利÷平均净亏损绝对值；盈利因子＝总净盈利÷总净亏损绝对值。没有盈利段或亏损段时盈亏比不计算。`;
 $('episodes').innerHTML=es.slice(-100).reverse().map(e=>`<tr><td>${e.symbol} · ${e.direction}</td><td>${e.entry_date}</td><td>${e.exit_date}</td><td>${fmt(e.gross)}</td><td>${fmt(e.cost)}</td><td style="color:${e.net>0?colors.fast:colors.red}">${fmt(e.net)}</td></tr>`).join('')||'<tr><td colspan="6">当前范围没有已平持仓段。</td></tr>';
}
function refresh(){if(!D)return;const start=$('start').value,end=$('end').value;if(!start||!end||start>end){$('rangeInfo').textContent='请设置有效的起止日期。';return}const p=D.products[$('product').value];rows=p.rows.filter(r=>r.date>=start&&r.date<=end);allEvents=p.events.filter(e=>e.date>=start&&e.date<=end);events=allEvents.filter(e=>e.roll?$('showRoll').checked:['加仓','减仓'].includes(e.kind)?$('showAdjust').checked:$('showSignals').checked);page=0;selected=null;renderTradeStats();$('tradeDetail').innerHTML='<p class="muted">选择一个交易标记，查看归档成交与决策。</p>';$('rangeInfo').textContent=`${p.name} · ${rows.length} 个交易日 · 归档日线`;renderTable();renderCharts();if(events.length)selectEvent(events[0]);else $('tradeDetail').innerHTML='<p class="muted">所选品种与区间没有符合筛选的成交。原始信号和仓位仍按档案展示，不补造成交。</p>';if(!rows.length)$('dayInfo').textContent='当前范围没有展示行情。'}
function stepsFor(){return [[D.meta.rule,D.meta.note],['信号缩放与限幅',`当前方案原始预测乘以标量 ${fmt(D.parameters.forecast_scalar,6)}，再限制在 ±${D.parameters.forecast_cap}。原始规则信号和最终forecast均直接读取归档。${D.meta.warning||''}`],['权益比例风险仓位','账户权益、16%年化风险预算、每日有效品种权重、合约乘数、价格波动率与信号共同决定连续仓位。这里是全品种组合的一项规则，不是将全部资金放入当前品种。'],['缓冲带、整数手数与执行','归档连续仓位经过缓冲和整数处理形成目标；委托日与成交日分开。换月平旧与开新按真实合约记录。日线撮合未建模完整保证金、强平、容量或真实盘中路径。']]}
function flow(i){if(!D)return;const steps=stepsFor();$('flowDetail').innerHTML=`<b>${steps[i][0]}</b><p>${steps[i][1]}</p>`;document.querySelectorAll('[data-step]').forEach(b=>b.classList.toggle('selected',+b.dataset.step===i))}document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>flow(+b.dataset.step));flow(0);
$('product').onchange=refresh;$('apply').onclick=refresh;['showSignals','showAdjust','showRoll'].forEach(id=>$(id).onchange=refresh);$('pagePrev').onclick=()=>{page--;renderTable()};$('pageNext').onclick=()=>{page++;renderTable()};for(const [id,delta] of [['prevEvent',-1],['nextEvent',1]])$(id).onclick=()=>{if(!events.length)return;const i=events.findIndex(e=>e.id===selected?.id);selectEvent(events[(i+delta+events.length)%events.length])};


const C=window.CARVER_CATALOG,loads=new Map();let requestToken=0;
function runLink(){return 'sources/'+D.meta.id+'-run.json'}
function choose(id){if(location.hash==='#'+id)loadStrategy(id);else location.hash=id}
function moduleLoad(meta){if(window.CARVER_SETS?.[meta.id])return Promise.resolve(window.CARVER_SETS[meta.id]);if(loads.has(meta.id))return loads.get(meta.id);const promise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=meta.data_file;script.onload=()=>resolve(window.CARVER_SETS[meta.id]);script.onerror=()=>{loads.delete(meta.id);script.remove();reject(new Error('数据加载失败，请重新选择或刷新页面。'))};document.head.appendChild(script)});loads.set(meta.id,promise);return promise}
function disableControls(value){document.querySelectorAll('.toolbar input,.toolbar button,.toolbar select,.toggles input,.toggles button').forEach(e=>e.disabled=value);document.body.classList.toggle('loading',value)}
async function loadStrategy(id){const meta=C.strategies.find(x=>x.id===id)||C.strategies.find(x=>x.id===C.default),token=++requestToken;disableControls(true);$('loadState').textContent='正在载入 '+meta.name+'…';try{const next=await moduleLoad(meta);if(token!==requestToken)return;if(!next)throw new Error('策略数据未返回');D=next;
 $('strategyTitle').innerHTML=`${meta.english} <span>${meta.name}</span>`;$('strategyDescription').textContent=meta.note;$('strategyVersion').innerHTML=`${meta.id} / ${meta.version}<b>${meta.label}</b><small>${meta.params}</small>`;
 $('strategyWarning').hidden=!meta.warning;$('strategyWarning').textContent=meta.warning||'';$('start').min=D.chart_start;$('end').min=D.chart_start;if($('start').value<D.chart_start||$('end').value<D.chart_start){$('start').value='2024-01-01';$('end').value='2025-12-31';}$('strategySwitch').value=meta.id;document.querySelectorAll('[data-strategy]').forEach(b=>b.classList.toggle('active',b.dataset.strategy===meta.id));
 $('priceLegend').innerHTML='<i class="price"></i>信号价'+(['S003','S007'].includes(meta.id)?'<i class="fast"></i>EMA16 <i class="slow"></i>EMA64':meta.id==='S004'?'<i class="fast"></i>20日上沿 <i class="slow"></i>20日下沿':'');
 $('rawDescription').textContent='直接读取归档决策 raw_forecast；缩放前';$('ruleFeature').textContent=meta.rule;
 $('ruleSource').href='sources/'+meta.id+'-rules.txt';$('ruleSource').textContent='规则说明与研究笔记 · '+meta.id+' ↗';$('runSource').href=runLink();$('codeSource').href='https://github.com/pst-group/pysystemtrade/blob/164328bd76d2937d3dd61491377704c488283bc2/systems/provided/rules/'+meta.module+'.py';$('codeSource').textContent='作者源码 · '+meta.module+'.py ↗';
 document.querySelector('[data-step="0"]').textContent='① 原始规则';renderMetrics();flow(0);refresh();$('loadState').textContent=meta.id+' · '+meta.label+' · 归档已载入';
 }catch(error){if(token===requestToken){$('loadState').textContent=error.message;if(D)$('strategySwitch').value=D.meta.id}}finally{if(token===requestToken)disableControls(false)}}
$('strategyNav').innerHTML=C.strategies.map(s=>`<button data-strategy="${s.id}">${s.name}<small>${s.id} · ${s.label}</small></button>`).join('');$('strategySwitch').innerHTML=C.strategies.map(s=>`<option value="${s.id}">${s.id} · ${s.name}</option>`).join('');document.querySelectorAll('[data-strategy]').forEach(b=>b.onclick=()=>choose(b.dataset.strategy));$('strategySwitch').onchange=()=>choose($('strategySwitch').value);
$('strategyOverview').innerHTML=C.strategies.map(s=>`<tr data-open="${s.id}"><td>${s.name}<br><small>${s.label}${s.warning?' · 诊断':''}</small></td><td>${s.metrics.start}</td><td>${fmt(s.metrics.cagr_natural_pct)}%</td><td>${fmt(s.metrics.max_drawdown_pct)}%</td><td>${fmt(s.trade_summary.win_rate_pct)}%</td><td>${s.trade_summary.payoff_ratio==null?'不可计算':fmt(s.trade_summary.payoff_ratio)+' 倍'}</td></tr>`).join('');document.querySelectorAll('[data-open]').forEach(r=>r.onclick=()=>choose(r.dataset.open));
window.addEventListener('hashchange',()=>loadStrategy(location.hash.slice(1)));loadStrategy(location.hash.slice(1)||C.default);

$('tradeExample').onclick=()=>{if(!D?.trade_example)return;const e=D.trade_example,at=new Date(e.date+'T12:00:00Z'),a=new Date(at),b=new Date(at);a.setUTCDate(a.getUTCDate()-180);b.setUTCDate(b.getUTCDate()+60);$('start').value=[a.toISOString().slice(0,10),D.chart_start].sort().at(-1);$('end').value=[b.toISOString().slice(0,10),D.metrics.end].sort()[0];$('product').value=e.product;['showSignals','showAdjust','showRoll'].forEach(id=>$(id).checked=true);refresh()};
